using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Net;using System.Net.NetworkInformation;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
public class NodeConfig{public int Version,RemotePort;public bool RequiresPassword;public string NodeId,Label,Server,Username,Password,SsPassword,TransportKey,KnownHosts;}
public sealed class ConnectorCore:IDisposable{
 public int Port;public string Runtime;Common.Job job;readonly List<Process> children=new List<Process>();readonly Action<string> log;
 public ConnectorCore(Action<string> l){log=l;}
 public static void Validate(NodeConfig c){if(c==null||c.Version!=2||c.Server!="203.0.113.20"||c.RemotePort<25000||c.RemotePort>=25032||c.Username!="node"+(c.RemotePort-25000+1).ToString("000")||!System.Text.RegularExpressions.Regex.IsMatch(c.Password??"","^[a-f0-9]{64}$")||!System.Text.RegularExpressions.Regex.IsMatch(c.SsPassword??"","^[a-f0-9]{64}$")||String.IsNullOrEmpty(c.TransportKey)||!System.Text.RegularExpressions.Regex.IsMatch(c.NodeId??"","^[a-f0-9]{32}$"))throw new Exception("不是有效的 V2 节点连接配置");
  try{var lines=(c.KnownHosts??"").Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);if(lines.Length!=1)throw new Exception();var p=lines[0].Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries);if(p.Length!=3||(p[0]!="203.0.113.20"&&p[0]!="[203.0.113.20]:22")||p[1]!="ssh-ed25519")throw new Exception();using(var h=System.Security.Cryptography.SHA256.Create())if(Convert.ToBase64String(h.ComputeHash(Convert.FromBase64String(p[2]))).TrimEnd('=')!="kjA1RMqdAwils/qwLFqtwuiST8tfUX+0VNQXiD91TGs")throw new Exception();}catch{throw new Exception("节点配置中的服务器指纹不匹配");}
 }
 Process Launch(string exe,string args){var p=new Process{StartInfo=new ProcessStartInfo(exe,args){WorkingDirectory=Runtime,UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true}};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null&&!e.Data.StartsWith("debug")&&!e.Data.StartsWith("Authenticated")&&!e.Data.StartsWith("OpenSSH_"))log(e.Data);};p.Start();job.Add(p);children.Add(p);p.BeginErrorReadLine();p.BeginOutputReadLine();return p;}
 void WaitPort(int port){for(int i=0;i<150;i++){if(children.Any(p=>p.HasExited))throw new Exception("连接进程退出，请检查网络或节点配置");if(IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpListeners().Any(p=>p.Address.Equals(IPAddress.Loopback)&&p.Port==port))return;Thread.Sleep(100);}throw new Exception("等待连接端口超时");}
 public void Start(NodeConfig c,int port){Validate(c);Common.Verify();if(port<1024||port>65532)throw new Exception("本地端口范围应为 1024—65532");for(int i=0;i<3;i++){var l=new System.Net.Sockets.TcpListener(IPAddress.Loopback,port+i);try{l.Start();}catch{throw new Exception("本地端口 "+(port+i)+" 已占用；请换端口，或自行停止旧连接器。");}finally{l.Stop();}}
  Port=port;var a=Common.Adapters().FirstOrDefault();if(a==null)throw new Exception("没有找到物理网络");Runtime=Path.Combine(Common.Base,"runtime","run-"+Guid.NewGuid().ToString("N"));Common.PrivateDir(Runtime);job=new Common.Job();File.WriteAllText(Path.Combine(Runtime,"client_key"),c.TransportKey.Replace("\r\n","\n"),new UTF8Encoding(false));File.WriteAllText(Path.Combine(Runtime,"known_hosts"),c.KnownHosts,new UTF8Encoding(false));int local=Common.FreePort();
  string cfg="Host relay\n HostName "+c.Server+"\n Port 22\n User gost-home-v2-client\n IdentityFile "+Common.Q(Path.Combine(Runtime,"client_key"))+"\n UserKnownHostsFile "+Common.Q(Path.Combine(Runtime,"known_hosts").Replace('\\','/'))+"\n StrictHostKeyChecking yes\n IdentitiesOnly yes\n BatchMode yes\n ForwardAgent no\n ConnectTimeout 15\n ServerAliveInterval 15\n ServerAliveCountMax 2\n ExitOnForwardFailure yes\n ProxyCommand "+Common.Q(Path.Combine(Common.Base,"NetBridge.exe").Replace('\\','/'))+" "+a.Index+" "+a.Address+" %h %p\n";
  File.WriteAllText(Path.Combine(Runtime,"ssh_config"),cfg,new UTF8Encoding(false));Launch(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32","OpenSSH","ssh.exe"),"-v -F "+Common.Q(Path.Combine(Runtime,"ssh_config"))+" -N -T -L 127.0.0.1:"+local+":127.0.0.1:"+c.RemotePort+" relay");WaitPort(local);
  var chain=Common.D("name","node","hops",new[]{Common.D("name","encrypted-ssh","nodes",new[]{Common.D("name","server","addr","127.0.0.1:"+local,"connector",Common.D("type","socks5","auth",Common.D("username",c.Username,"password",c.Password),"metadata",Common.D("notls",true,"udpBufferSize",65535)),"dialer",Common.D("type","tcp"))})});
  var services=new List<object>{Common.D("name","local-socks5","addr","127.0.0.1:"+port,"handler",Common.D("type","socks5","chain","node","metadata",Common.D("udp",true,"notls",true,"udpBufferSize",65535)),"listener",Common.D("type","tcp")),Common.D("name","local-http","addr","127.0.0.1:"+(port+1),"handler",Common.D("type","http","chain","node"),"listener",Common.D("type","tcp"))};
  foreach(string type in new[]{"tcp","udp"})services.Add(Common.D("name","local-ss-"+type,"addr","127.0.0.1:"+(port+2),"handler",Common.D("type",type=="tcp"?"ss":"ssu","chain","node","auth",Common.D("username","chacha20-ietf-poly1305","password",c.SsPassword)),"listener",Common.D("type",type)));
  var gost=Common.D("services",services,"chains",new[]{chain},"log",Common.D("level","warn","format","json","output","stderr"));File.WriteAllText(Path.Combine(Runtime,"client.json"),Common.Json.Serialize(gost),new UTF8Encoding(false));Launch(Path.Combine(Common.Base,"gost.exe"),"-C "+Common.Q(Path.Combine(Runtime,"client.json")));WaitPort(port);log("SOCKS5：127.0.0.1:"+port+"；HTTP：127.0.0.1:"+(port+1)+"；Shadowsocks：127.0.0.1:"+(port+2));
 }
 public void Dispose(){if(job!=null){job.Dispose();job=null;}foreach(var p in children)try{if(!p.HasExited)p.Kill();p.WaitForExit(1000);p.Dispose();}catch{}children.Clear();if(Runtime!=null){Common.Clean(Runtime,Path.Combine(Common.Base,"runtime"));Runtime=null;}}
}
